-- Execute as the managed Storage table owner through the provider migration service.
-- No GRANT of supabase_storage_admin and no ownership/role changes are part of this patch.
-- Existing policies are retained; these constraints only narrow their permissions.
CREATE POLICY shared_storage_read ON storage.objects AS RESTRICTIVE FOR SELECT TO authenticated USING(public.shared_storage_session_access('view') AND (bucket_id NOT IN('user-files','media','chat-attachments','whatsapp-media') OR public.shared_storage_access(bucket_id,name,'view')));
CREATE POLICY shared_storage_create ON storage.objects AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(public.shared_storage_session_access('create') AND (bucket_id NOT IN('user-files','media','chat-attachments','whatsapp-media') OR public.shared_storage_access(bucket_id,name,'create')));
CREATE POLICY shared_storage_update ON storage.objects AS RESTRICTIVE FOR UPDATE TO authenticated USING(public.shared_storage_session_access('update') AND (bucket_id NOT IN('user-files','media','chat-attachments','whatsapp-media') OR public.shared_storage_access(bucket_id,name,'update'))) WITH CHECK(public.shared_storage_session_access('update') AND (bucket_id NOT IN('user-files','media','chat-attachments','whatsapp-media') OR public.shared_storage_access(bucket_id,name,'update')));
CREATE POLICY shared_storage_delete ON storage.objects AS RESTRICTIVE FOR DELETE TO authenticated USING(public.shared_storage_session_access('delete') AND (bucket_id NOT IN('user-files','media','chat-attachments','whatsapp-media') OR public.shared_storage_access(bucket_id,name,'delete')));
